function fullSentence(q){return q.context.includes('___')?q.context.replace('___',q.answers[0]):q.answers[0];}
function redParts(text,why){const re=/\[\[([^|]+)\|([^\]]+)\]\]/g;let match,last=0,parts=[],errors=[];while((match=re.exec(text))){if(match.index>last)parts.push({text:text.slice(last,match.index)});const ix=errors.length;parts.push({text:match[1],error:ix});errors.push(item(`Corrija “${match[1]}”.`,match[2],why,match[1]));last=re.lastIndex;}if(last<text.length)parts.push({text:text.slice(last)});return {parts,items:errors};}
for(let ui=0;ui<18;ui++){
 const u=UNITS[ui],[person,scene,message]=CHAT_CONTEXTS[ui],q=u.items[0];
 const chatItem=sourceItem(q);if(ui===16)chatItem.prompt='Complete apenas o trecho que falta.';
 addGame(ui,'chat','Uma conversa com '+CAST[person].name,{person,scene,messages:[message],items:[chatItem]});
 const [docTitle,docText,docWhy]=RED_DOCS[ui];addGame(ui,'redpen','Um rascunho para salvar',{docTitle,...redParts(docText,docWhy)});
 const spoken=fullSentence(u.items[1]);addGame(ui,'dictation','Ouça antes de responder',{person:ui%2?'mia':'leo',sentence:spoken,items:[item('Digite a mensagem que você ouviu.',spoken,u.items[1].why)]});
 const speakSentence=fullSentence(u.items[4]);addGame(ui,'speak','Tire a frase do papel',{scene:ui<9?'Envie esta frase em uma mensagem de voz.':'Deliver this line clearly in a professional conversation.',sentence:speakSentence,items:[item('Diga a frase em voz alta.',speakSentence,u.items[4].why)]});
 const [tonePrompt,toneSource,toneAnswer,toneWhy]=TONES[ui];addGame(ui,'tone','Uma mudança de registro',{items:[item(tonePrompt,toneAnswer,toneWhy,toneSource)]});
 const [artifactTitle,artifact,prompt,answer,why]=READINGS[ui];addGame(ui,'reading','Um detalhe faz a diferença',{artifactTitle,artifact,items:[item(prompt,answer,why)]});
 addGame(ui,'memory','Conecte as ideias',{seconds:60,pairs:PAIRS[ui],items:PAIRS[ui].map(([a,b])=>item(`O que combina com “${a}”?`,b,`${a} → ${b}`,a))});
 const target=u.items[3].answers[0],words=target.split(' '),missing=Math.max(1,Math.floor(words.length/2));addGame(ui,'surgery','A palavra fora do lugar',{word:words[missing],tokens:words.filter((_,i)=>i!==missing),slot:missing,items:[item('Toque no ponto onde a palavra deve entrar.',target,u.items[3].why)]});
 const [wrong,fixed,trapWhy]=TRAPS[ui];addGame(ui,'trap','Parece português. Mas é inglês.',{items:[item('Reescreva corrigindo a armadilha.',fixed,trapWhy,wrong)]});
 const [storyTitle,storyPerson,steps]=STORIES[ui];addGame(ui,'story',storyTitle,{person:storyPerson,items:steps.map(([prompt,options,correct,why,bad])=>({...item(prompt,options[correct],why),options,correct,bad}))});
}
